import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FlatSolver solver = new FlatSolver();
        solver.solve(1, in, out);
        out.close();
    }

    static class FlatSolver {
        static final int MOD = 1_000_000_007;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            out.print(calculate(n));
        }

        private int calculate(int n) {
            int size = 2 * n + 1;
            if (size < 0) {
                throw new NegativeArraySizeException();
            }

            int[] dp = new int[size * size * 2];
            dp[((0 * size + 0) << 1) + 0] = 1;

            for (int depth = 1; depth <= 2 * n; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    int base = ((depth * size + opened) << 1);
                    int bit0 = base;
                    int bit1 = base + 1;

                    if (opened > 0) {
                        int prevBase = (((depth - 1) * size + (opened - 1)) << 1);
                        dp[bit0] += dp[prevBase + 1];
                        dp[bit1] += dp[prevBase];
                    }
                    if (opened + 1 < size) {
                        int prevBase = (((depth - 1) * size + (opened + 1)) << 1);
                        dp[bit0] += dp[prevBase + 1];
                        dp[bit1] += dp[prevBase];
                    }

                    dp[bit0]++;
                    dp[bit0] %= MOD;
                    dp[bit1] %= MOD;
                }
            }

            int finalBase = ((2 * n * size + 0) << 1);
            return dp[finalBase + 1];
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void close() {
            writer.close();
        }

        public void print(int i) {
            writer.print(i);
        }
    }
}
